contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}

    function run(uint256 vBase, uint256 vNft, uint256 feeRate_, uint256 protocolFeeRate_, uint256 weight, uint256 value) public payable {
        require(vBase > 0 && vNft > 0 && feeRate_ <= 5000 && protocolFeeRate_ <= 10000 && weight > 0);
        require(address(this).balance >= value);

        c.initialize(address(0), address(this), uint128(vBase), uint128(vNft), 0, uint16(feeRate_), bytes32(0), false, false);

        uint256[] memory ids = new uint256[](1);
        ids[0] = 1;
        uint256[] memory weights = new uint256[](1);
        weights[0] = weight;
        C.MerkleMultiProof memory proof;

        uint256 baseBefore = address(c).balance;
        (bool success, bytes memory ret) = address(c).call{value: value}(abi.encodeWithSignature("buy(uint256[],uint256[],((bytes32[],bool[])))", ids, weights, proof));
        require(success, "buy failed");
        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = abi.decode(ret, (uint256, uint256, uint256));

        uint256 baseAfter = address(c).balance;

        uint256 protocolFeeAmount_ = netInputAmount * protocolFeeRate_ / 10000;
        uint256 feeAmount_ = netInputAmount * feeRate_ / 10000;
        uint256 totalAmt = netInputAmount + feeAmount_ + protocolFeeAmount_;

        assert(baseAfter - baseBefore <= totalAmt);
    }
}

