contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        C.MerkleMultiProof calldata proof,
        IStolenNftOracle.Message[] memory stolenNftProofs
    ) public payable {
        require(tokenIds.length == tokenWeights.length, "length mismatch");

        uint256 weightSum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof);

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(weightSum);

        uint128 vNftBefore = c.virtualNftReserves();
        uint128 vBaseBefore = c.virtualBaseTokenReserves();

        uint256 returnedNet;
        bool reverted;
        try c.sell(tokenIds, tokenWeights, proof, stolenNftProofs) returns (uint256 noa, uint256, uint256) {
            returnedNet = noa;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint128 vNftAfter = c.virtualNftReserves();
            uint128 vBaseAfter = c.virtualBaseTokenReserves();

            assert(vNftAfter == vNftBefore + uint128(weightSum));
            assert(returnedNet <= netOutputAmount);
            assert(vBaseBefore == vBaseAfter + uint128(netOutputAmount + feeAmount + protocolFeeAmount));
        } else {
            assert(c.virtualNftReserves() == vNftBefore);
            assert(c.virtualBaseTokenReserves() == vBaseBefore);
        }
    }

    receive() external payable {}
}

